// A CommonJS helper both native code and an island require: its exports
// are declarations, so each side's copy is unobservable.
module.exports = once;
once.strict = onceStrict;
function once(fn) {
  var f = function () {
    if (f.called) return f.value;
    f.called = true;
    return (f.value = fn.apply(this, arguments));
  };
  f.called = false;
  return f;
}
function onceStrict(fn) {
  var f = once(fn);
  return f;
}
